// Prepare incoming Telegram text for the Mizan backend.
function prepareUpdate(update, config) {
  const message = update?.message;
  if (!message || message.from?.is_bot || !Number.isSafeInteger(message.chat?.id)) return null;
  const text = typeof message.text === 'string' ? message.text : typeof message.caption === 'string' ? message.caption : '';
  const context = {chat_id:String(message.chat.id),message_id:message.message_id,text,config,should_check:false,service_text:''};
  const command = text.trim().split(/\s/)[0].split('@')[0];
  if (['/start','/help'].includes(command)) context.service_text = 'مرحبًا بك في ميزان. أرسل نصًا يحتوي على آية أو حديث للتحقق من مصادره. أداة آلية وليست فتوى.';
  else if (!text.trim()) context.service_text = 'أرسل نصًا أو صورة / فيديو مع وصف يحتوي على الاقتباس. لا تدعم هذه النسخة قراءة النص داخل الصور أو التسجيلات الصوتية.';
  else if (Array.from(text).length > 4000) context.service_text = 'النص طويل. اختصره إلى 4000 حرف ثم أرسله مجددًا.';
  else context.should_check = true;
  return context;
}
