const LIMIT = 3900;
function escapeHtml(value) {
  return String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function sourceLink(url, label = 'عرض المصدر') {
  if (typeof url !== 'string' || url.includes(String.fromCharCode(92)) || !/^https:\/\/[a-z0-9](?:[a-z0-9.-]*[a-z0-9])?(?::\d{1,5})?(?:[/?#][^\s<>"]*)?$/i.test(url)) return ''; return `<a href="${escapeHtml(url)}">${escapeHtml(label)}</a>`;
}
