}
function claimBlock(claim) {
  if (!claim || typeof claim.span !== 'string') throw new Error('Invalid claim');
  const verdicts = { verified: '✓ موثّق', misquoted: '⚠ منقول بخطأ', not_established: '✕ لا يثبت', disputed: '⚖ اختلف المحدثون', not_found: '? لم يُعثر عليه', needs_review: '? يحتاج مراجعة مختص' };
  const lines = [`<b>${claim.source_status === 'source_unavailable' ? '! تعذر الوصول للمصدر' : verdicts[claim.verdict] || verdicts.needs_review}</b>`, `«${escapeHtml(claim.span)}»`];
  if (claim.source_status === 'source_unavailable') lines.push('المصدر لم يستجب. أعد المحاولة؛ هذا لا يعني عدم وجود الاقتباس.');
  else if (claim.verdict === 'not_found') lines.push('لم نجد مرجعًا مطابقًا في المصادر المتاحة. راجع جهة مؤهلة قبل نسبة النص.');
  if (['disputed', 'needs_review'].includes(claim.verdict)) lines.push('تحتاج النتيجة إلى مراجعة مختص. تُعرض أحكام المصادر دون ترجيح.');
  if (claim.verdict === 'verified' && claim.relation === 'same_meaning') lines.push('ثابت بالمعنى، واللفظ المعتمد هو النص الوارد في المصدر.');
  if (claim.verdict === 'misquoted') lines.push('لا تعتمد على النص المنقول بصيغته الحالية.');
  const evidence = claim.evidence;
  if (evidence?.text_arabic) lines.push(`<b>${claim.verdict === 'misquoted' ? 'النص الصحيح' : 'النص العربي من المصدر'}</b>\n${escapeHtml(evidence.text_arabic)}`);
  if (evidence?.translation) lines.push(escapeHtml(evidence.translation));
  for (const grade of evidence?.gradings || []) lines.push([grade.grade_text && `حكم المصدر: ${grade.grade_text}`, grade.mohaddith, grade.book, grade.page != null && `الصفحة / الرقم: ${grade.page}`].filter(Boolean).map(escapeHtml).join('\n'));
  for (const location of evidence?.locations || []) lines.push(`السورة: ${escapeHtml(location.surah_name_ar || location.surah)} · الآية: ${escapeHtml(location.ayah)}`);
  if (evidence?.source) lines.push(`المصدر: ${escapeHtml(({ dorar: 'الدرر السنية', quran: 'النص القرآني المعتمد', hadeethenc: 'موسوعة الأحاديث النبوية' })[evidence.source] || evidence.source)}`);
  if (evidence?.url) lines.push(sourceLink(evidence.url));
  if (claim.diff?.details) lines.push(`الفروق: ${escapeHtml(claim.diff.details)}`);
  for (const op of claim.diff?.ops || []) lines.push([op.quoted && `المنقول: ${escapeHtml(op.quoted)}`, op.source && `الصحيح: ${escapeHtml(op.source)}`].filter(Boolean).join(' ← '));
  if (claim.alternative) lines.push('<b>بديل صحيح — حديث آخر في المعنى نفسه</b>', escapeHtml(claim.alternative.text_arabic), escapeHtml(claim.alternative.translation || ''), escapeHtml(claim.alternative.attribution || ''), sourceLink(claim.alternative.url, 'مصدر البديل'));
  return lines.filter(Boolean).join('\n\n');
}
function formatResponse(response, context, loadingMessageId) {
  const prefix = context.config.demo ? '<b>عرض تجريبي — نتائج ثابتة</b>\n\n' : '';
  const envelope = response?.body !== undefined ? response.body : response;
  const footer = '\n\nأداة آلية للتحقق من المصادر، وليست فتوى.';
  let blocks = [];
  try {
    if (response?.error || response?.statusCode >= 400) blocks = [errorText(response.statusCode)];
    else if (envelope?.status === 'demo_unsupported' && context.config.demo) blocks = ['هذه نسخة تجريبية. أرسل: اطلبوا العلم ولو بالصين\nالتحقق من نصوص أخرى يتطلب ربط الـBackend.'];
    else {
      if (!envelope || !['ok', 'no_claims', 'evidence_request', 'referral'].includes(envelope.status) || !Array.isArray(envelope.claims)) throw new Error('Invalid response');
      const titles = { no_claims: 'لم نجد آية أو حديثًا مقتبسًا في النص.', evidence_request: 'مِيزان يتحقق من الأدلة الموجودة، ولا ينشئ أدلة جديدة.', referral: 'هذا السؤال يحتاج إلى جهة مؤهلة للإفتاء.' };
      if (envelope.status !== 'ok') blocks.push([titles[envelope.status], escapeHtml(envelope.message || ''), escapeHtml(envelope.referral?.text || '')].filter(Boolean).join('\n\n'));
      blocks.push(...envelope.claims.map(claimBlock));
      if (!blocks.length) throw new Error('Empty result');
    }
  } catch { blocks = ['وصلت نتيجة لا يمكن عرضها بأمان. حاول مرة أخرى لاحقًا.']; }
  const details = envelope?.check_id && context.config.website_url ? sourceLink(`${context.config.website_url.replace(/\/$/, '')}/result/${encodeURIComponent(envelope.check_id)}`, 'عرض التفاصيل في مِيزان') : '';
  const chunks = []; let current = '';
  for (let block of blocks) {
    // A single oversized card is summarized with links, never cut mid-sentence or mid-HTML entity.
    if ((prefix + block + footer + '\n' + details).length > LIMIT) block = 'نتيجة طويلة لا يمكن عرضها كاملة في رسالة واحدة. راجع التفاصيل والمصادر.\n' + details + '\n' + (envelope?.claims || []).map(c => sourceLink(c.evidence?.url)).filter(Boolean).join('\n');
    if ((prefix + block + footer).length > LIMIT) block = 'نتيجة طويلة لا يمكن عرضها كاملة. افتح صفحة النتيجة في مِيزان.';
    const next = current ? current + '\n\n────────\n\n' + block : block;
    if ((prefix + next + footer).length > LIMIT) { chunks.push(prefix + current + footer); current = block; } else current = next;
  }
  if (current) chunks.push(prefix + current + footer);
  if (details && chunks.length && (chunks[chunks.length - 1] + '\n' + details).length <= LIMIT) chunks[chunks.length - 1] += '\n' + details;
  return chunks.map((text, index) => ({ chat_id: context.chat_id, text, loading_message_id: loadingMessageId, edit: index === 0 && Number.isInteger(loadingMessageId), part: index }));
}

